import sys
from collections import OrderedDict
data = sys.stdin.read().split()
cap = int(data[0])
t = int(data[1])
idx = 2
cache = OrderedDict()
out = []
for _ in range(t):
 op = data[idx]; idx += 1
 if op == "PUT":
 k, v = data[idx], int(data[idx+1]); idx += 2
 if k in cache: cache.move_to_end(k)
 cache[k] = v
 if len(cache) > cap: cache.popitem(last=False)
 else:
 k = data[idx]; idx += 1
 if k in cache:
 cache.move_to_end(k)
 out.append(str(cache[k]))
 else:
 out.append("MISS")
print("\n".join(out))

